-- ============================================================================
-- Seed SQL: October 2026 Data Migration from Excel
-- Run this in Supabase SQL Editor AFTER you have signed up your account.
-- Replace 'YOUR_USER_ID_HERE' with your actual Supabase auth user UUID,
-- OR this script automatically fetches the first user ID from auth.users.
-- ============================================================================

DO $$
DECLARE
    target_user_id UUID;
BEGIN
    -- Automatically selects your user ID if you are the only user in auth.users
    SELECT id INTO target_user_id FROM auth.users ORDER BY created_at ASC LIMIT 1;
    IF target_user_id IS NULL THEN
        RAISE NOTICE 'No user found in auth.users! Sign up in your app first, then run this seed.';
        RETURN;
    END IF;

    -- Insert October 2026 Budget
    VALUES (target_user_id, 2026, 10, 12510.0)
    ON CONFLICT (user_id, year, month) DO UPDATE SET budget = EXCLUDED.budget;

    -- Insert October 2026 Daily Expenses

    RAISE NOTICE 'Successfully seeded October 2026 budget (₹%) and % days of expenses!', 12510.0, 31;
END $$;
